import * as THREE from 'three/webgpu';
import { color, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    CircleGeometry,
    Color,
    Vector3
  } = ctx.THREE;

  const visualSpec = config.intent?.visualSpec ?? {};
  const palette = visualSpec.colors ?? {};
  const ink = palette.ink ?? '#16161d';
  const paper = palette.paper ?? '#e8ecf2';
  const accent = palette.accent ?? '#ff2a38';
  const surface = palette.surface ?? '#0b0b10';

  const root = new Group();
  root.name = config.id ?? 'journal-card-2';

  const timelines = [];
  const primitiveCleanups = [];
  const ownedResources = [];
  let disposed = false;
  let focused = false;

  const addTween = (target, vars) => {
    const tween = gsap.to(target, vars);
    timelines.push(tween);
    return tween;
  };

  const makeBasicMaterial = (options = {}) => {
    const material = new THREE.MeshBasicNodeMaterial(options);
    ownedResources.push(material);
    return material;
  };

  const stageMaterial = makeBasicMaterial();
  stageMaterial.colorNode = mix(color(surface), color(ink), uv().y);

  const stage = new Mesh(new PlaneGeometry(7, 6), stageMaterial);
  stage.name = 'designed-gradient-backdrop';
  stage.position.set(0, 0, -2.5);
  root.add(stage);
  ownedResources.push(stage.geometry);

  const shadowMaterial = makeBasicMaterial({
    color: new Color(ink),
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });

  const contactShadow = new Mesh(
    new CircleGeometry(1.8, 48),
    shadowMaterial
  );
  contactShadow.name = 'radial-contact-shadow';
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.scale.set(1.25, 0.58, 1);
  contactShadow.position.set(0, -1.03, -0.08);
  root.add(contactShadow);
  ownedResources.push(contactShadow.geometry);

  const cardGroup = new Group();
  cardGroup.name = 'journal-card';
  cardGroup.position.set(0, 0, 0);
  root.add(cardGroup);

  const cardMaterial = makeBasicMaterial({
    color: new Color(paper)
  });

  const card = new Mesh(new PlaneGeometry(3.2, 2), cardMaterial);
  card.name = 'journal-card-image';
  cardGroup.add(card);
  ownedResources.push(card.geometry);

  const frameMaterial = makeBasicMaterial({
    color: new Color(ink)
  });

  const focusMaterial = makeBasicMaterial({
    color: new Color(ink)
  });

  const framePieces = [
    { size: [3.28, 0.045, 0.08], position: [0, 1.025, 0.075] },
    { size: [3.28, 0.045, 0.08], position: [0, -1.025, 0.075] },
    { size: [0.045, 2.0, 0.08], position: [-1.62, 0, 0.075] },
    { size: [0.045, 2.0, 0.08], position: [1.62, 0, 0.075] }
  ];

  for (const piece of framePieces) {
    const edge = new Mesh(
      new BoxGeometry(piece.size[0], piece.size[1], piece.size[2]),
      focusMaterial
    );
    edge.position.set(piece.position[0], piece.position[1], piece.position[2]);
    edge.name = 'accent-focus-edge';
    cardGroup.add(edge);
    ownedResources.push(edge.geometry);
  }

  const cornerMarker = new Mesh(
    new BoxGeometry(0.16, 0.045, 0.09),
    makeBasicMaterial({ color: new Color(accent) })
  );
  cornerMarker.name = 'signal-red-accent';
  cornerMarker.position.set(-1.42, -0.78, 0.09);
  cardGroup.add(cornerMarker);
  ownedResources.push(cornerMarker.geometry);

  const items = config.textContent ?? visualSpec.textContent ?? [];
  let textOffset = -0.72;

  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: paper,
      align: item.typography?.align ?? 'left',
      maxWidthPx: item.typography?.maxWidthPx
    });

    textObject.name = `text-${item.role ?? 'label'}`;
    textObject.position.set(-1.36, textOffset, 0.13);
    cardGroup.add(textObject);
    textOffset -= 0.28;
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }

      texture.colorSpace = THREE.SRGBColorSpace;
      cardMaterial.map = texture;
      cardMaterial.needsUpdate = true;
      ownedResources.push(texture);
    });
  }

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    const result = ctx.primitives[primitive.name](
      root,
      primitive.params ?? {}
    );

    if (result?.cleanup) primitiveCleanups.push(result.cleanup);
    if (result?.timeline) timelines.push(result.timeline);
  }

  const setFocus = (active) => {
    focused = active;
    focusMaterial.color.set(active ? accent : ink);
    focusMaterial.needsUpdate = true;
  };

  root.userData.handlers = {
    hover: (active = true) => {
      if (disposed) return;

      if (active) {
        addTween(cardGroup.position, {
          y: 0.15,
          duration: 0.45,
          ease: 'power3.out',
          overwrite: true
        });
      } else {
        addTween(cardGroup.position, {
          y: 0,
          duration: 0.45,
          ease: 'power3.out',
          overwrite: true
        });
      }
    },

    pointerenter: () => root.userData.handlers.hover(true),
    pointerleave: () => root.userData.handlers.hover(false),

    focus: () => setFocus(true),
    blur: () => setFocus(false),

    click: () => {
      if (disposed) return;

      addTween(cardGroup.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'power2.out',
        yoyo: true,
        repeat: 1,
        overwrite: true
      });

      ctx.emit('hub-journal.select', {
        nodeId: config.id ?? 'journal-card-2',
        source: 'journal-card'
      });
    }
  };

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const cleanup of primitiveCleanups) {
      cleanup?.();
    }

    for (const resource of ownedResources) {
      resource?.dispose?.();
    }

    root.userData.handlers = {};
  };

  return root;
}
